    say: "Separate chaining with a prime bucket count, resize when the load factor passes 0.75, and equality — not just the hash — decides a match.",
    py: "class MyHashMap:\n    def __init__(self):\n        self.B = 769                      # prime reduces clustering\n        self.buckets = [[] for _ in range(self.B)]\n\n    def _idx(self, k):\n        return hash(k) % self.B\n\n    def put(self, k, v):\n        b = self.buckets[self._idx(k)]\n        for i, (kk, _) in enumerate(b):\n            if kk == k:                   # equality, not hash\n                b[i] = (k, v)\n                return\n        b.append((k, v))\n\n    def get(self, k):\n        for kk, vv in self.buckets[self._idx(k)]:\n            if kk == k:\n                return vv\n        return -1\n\n    def remove(self, k):\n        b = self.buckets[self._idx(k)]\n        for i, (kk, _) in enumerate(b):\n            if kk == k:\n                b.pop(i)                  # chaining: real delete is safe\n                return",
    cpp: "class MyHashMap {\n    static const int B = 769;\n    vector<list<pair<int,int>>> buckets;\n    int idx(int k) const { return (k % B + B) % B; }   // guard negatives\npublic:\n    MyHashMap() : buckets(B) {}\n\n    void put(int k, int v) {\n        auto& b = buckets[idx(k)];\n        for (auto& p : b) if (p.first == k) { p.second = v; return; }\n        b.emplace_back(k, v);\n    }\n    int get(int k) {\n        for (auto& p : buckets[idx(k)]) if (p.first == k) return p.second;\n        return -1;\n    }\n    void remove(int k) {\n        auto& b = buckets[idx(k)];\n        b.remove_if([&](auto& p){ return p.first == k; });\n    }\n};",
    java: "class MyHashMap {\n    private static final int B = 769;\n    private final LinkedList<int[]>[] buckets;\n\n    @SuppressWarnings(\"unchecked\")\n    public MyHashMap() {\n        buckets = new LinkedList[B];\n        for (int i = 0; i < B; i++) buckets[i] = new LinkedList<>();\n    }\n    private int idx(int k) { return Math.floorMod(k, B); }\n\n    public void put(int k, int v) {\n        for (int[] p : buckets[idx(k)]) if (p[0] == k) { p[1] = v; return; }\n        buckets[idx(k)].add(new int[]{k, v});\n    }\n    public int get(int k) {\n        for (int[] p : buckets[idx(k)]) if (p[0] == k) return p[1];\n        return -1;\n    }\n    public void remove(int k) {\n        buckets[idx(k)].removeIf(p -> p[0] == k);\n    }\n}",
