    cpp: "long long sortCount(vector<int>& a, int lo, int hi, vector<int>& buf) {\n    if (hi - lo <= 1) return 0;\n    int mid = (lo + hi) / 2;\n    long long inv = sortCount(a, lo, mid, buf) + sortCount(a, mid, hi, buf);\n    int i = lo, j = mid, k = lo;\n    while (i < mid && j < hi) {\n        if (a[i] <= a[j]) buf[k++] = a[i++];\n        else { buf[k++] = a[j++]; inv += mid - i; }   // all remaining left\n    }\n    while (i < mid) buf[k++] = a[i++];\n    while (j < hi)  buf[k++] = a[j++];\n    copy(buf.begin() + lo, buf.begin() + hi, a.begin() + lo);\n    return inv;                                        // long long: can exceed 2^31\n}",
